function s({registerIndicator:h,nulls:r}){h({id:"oa-ohl3",name:"Open-High-Low Average (OHL3)",category:"Numerics",placement:"onchart",inputs:[],plots:[{key:"ohl3",type:"line",title:"OHL3",style:{color:"#ffeb3b",lineWidth:2}}],calc(t){const o=new Array(t.length).fill(NaN);for(let e=0;e<t.length;e++){const n=t[e],i=n.open,l=n.high,c=n.low;!Number.isFinite(i)||!Number.isFinite(l)||!Number.isFinite(c)||(o[e]=(i+l+c)*.333333)}return{ohl3:r(o)}}})}export{s as default};
